<?php
/** TEMP PS S1617 run e12d — D: deploy v3.30.2 (v3.30.1 klaida: `//` komentaras array eilutėje nurijo 'kl' ir 'vez' — Klausimai neteko kortelių, vežėjas neapibrėžtas; sargai kaip e11d + ping). Q/Q2/T patikros. */
add_action('init', function(){
  if (!isset($_GET['ps_e12d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e12d'])); $o=array('v'=>'S1617 e12d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  try{
  if($f==='D'){
    $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
    $c2=''; $p1=(string)@file_get_contents($bk.'/dl-v3302.part1'); if(md5($p1)!=='9a063f347fcd979517e9d0ef349a0e1a'){ $o['STOP']='dalis 1 md5'; $J($o); }
    $gz=base64_decode($p1.$c2,true); $code=$gz===false?false:gzdecode($gz); if($code===false){ $o['STOP']='b64/gz'; $J($o); }
    $o['bytes']=strlen($code); $o['md5']=md5($code); if($o['md5']!=='9cc3a2da6a86a9177e6d57135425b78e'){ $o['STOP']='md5'; $J($o); }
    try { token_get_all($code, TOKEN_PARSE); $o['token']='ok'; } catch (Throwable $e) { $o['STOP']='token: '.$e->getMessage(); $J($o); }
    $t=WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'; $o['buvo']=file_exists($t)?md5_file($t):'NĖRA'; $o['klase_pries']=class_exists('Petshop_Darbalaukis');
    if(file_exists($t)&&!in_array($o['buvo'],array('c520a4c9beb8e70bfbc6906960f55886'),true)){ $o['STOP']='gyvas nežinomas ('.$o['buvo'].')'; $J($o); }
    if(file_exists($t)){ $o['backup']=copy($t,$bk.'/petshop-darbalaukis-v3301-BACKUP-'.date('Y-m-d-His').'.php'); }
    $o['rasyta']=file_put_contents($t,$code); $o['po']=md5_file($t); @unlink($bk.'/dl-v3302.part1'); if(function_exists('opcache_invalidate')){ @opcache_invalidate($t,true); }
    // NAUJAS SARGAS: ar svetainė pakyla su nauju failu (ši užklausa dar veikia su senu kodu)
    $r=wp_remote_get(admin_url('admin-ajax.php?action=heartbeat'),array('timeout'=>90,'sslverify'=>false)); $code_http=wp_remote_retrieve_response_code($r); $body=(string)wp_remote_retrieve_body($r);
    $o['ping']=array('code'=>$code_http,'fatal'=>(int)(stripos($body,'Fatal error')!==false||stripos($body,'Parse error')!==false),'body'=>mb_substr(wp_strip_all_tags($body),0,120));
    if($o['ping']['fatal']||$code_http>=500||is_wp_error($r)){ @unlink($t); $o['ATKURTA']='failas ištrintas atgal — svetainė be darbalaukio'; $o['po_atkurimo']=file_exists($t)?'DAR YRA':'nėra'; }
    $r2=wp_remote_get(admin_url('admin-ajax.php?action=heartbeat'),array('timeout'=>60,'sslverify'=>false)); $o['ping2']=array('code'=>wp_remote_retrieve_response_code($r2),'fatal'=>(int)(stripos((string)wp_remote_retrieve_body($r2),'Fatal error')!==false));
    do_action('ps_juosta_isvalyti'); $J($o);
  }
  $tu=get_user_by('login','testuotojas'); $uid=$tu->ID; $exp=time()+1800; $tok=WP_Session_Tokens::get_instance($uid)->create($exp); $li=wp_generate_auth_cookie($uid,$exp,'logged_in',$tok); $_COOKIE[LOGGED_IN_COOKIE]=$li; wp_set_current_user($uid);
  $cs=array(new WP_Http_Cookie(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'secure_auth',$tok))),new WP_Http_Cookie(array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'auth',$tok))),new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>$li)));
  if($f==='Q'){
    $r=wp_remote_get(admin_url('admin.php?page=ps-desk&eile=klausimai'),array('cookies'=>$cs,'timeout'=>90,'sslverify'=>false)); $h=(string)wp_remote_retrieve_body($r);
    $o['tabs']=preg_match_all('/<a[^>]*class="[^"]*dl-tab[^"]*"[^>]*>(.*?)<\/a>/su',$h,$ta)?array_map(function($x){return trim(preg_replace('/\s+/',' ',wp_strip_all_tags($x)));},$ta[1]):null;
    $o['nav_raw']=preg_match('/<nav[^>]*class="[^"]*dl-eiles[^"]*"[^>]*>(.*?)<\/nav>/su',$h,$nv)?trim(preg_replace('/\s+/',' ',wp_strip_all_tags($nv[1]))):mb_substr(trim(preg_replace('/\s+/',' ',wp_strip_all_tags(preg_match('/<main class="dl-main">(.*?)<div class="dl-kortele/su',$h,$mm)?$mm[1]:''))),0,400);
    $o['kort']=preg_match_all('/<div class="dl-kortele eil" data-id="(\d+)"/su',$h,$kk)?$kk[1]:array();
    $J($o);
  }
  if($f==='Q2'){
    $rm=new ReflectionMethod('Petshop_Darbalaukis','faktai'); $rm->setAccessible(true); $rz=new ReflectionMethod('Petshop_Darbalaukis','zurnalas'); $rz->setAccessible(true);
    foreach(array(35100,35423,35439) as $id){ $x=wc_get_order($id); $fk=$rm->invoke(null,$x,$rz->invoke(null,array($id))); $o['f'][$id]=array('st'=>$x->get_status(),'paid'=>$fk['paid'],'is_paid'=>$x->is_paid(),'date_paid'=>$x->get_date_paid()?$x->get_date_paid()->date('Y-m-d H:i'):null,'kl'=>$fk['kl'],'eiles'=>$fk['eiles'],'uzd'=>$fk['uzdarytas'],'sk'=>$fk['siuntos_klaida']?1:0,'laukti'=>(string)$x->get_meta('_ps_klaus_laukti'),'notes'=>array_map(function($n){return mb_substr($n->content,0,120);},wc_get_order_notes(array('order_id'=>$id,'limit'=>2)))); }
    $J($o);
  }
  if($f==='T'){
    $o['versija']=class_exists('Petshop_Darbalaukis')?Petshop_Darbalaukis::VERSIJA:'KLASĖS NĖRA'; $o['md5']=md5_file(WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php');
    $n=wp_create_nonce('ps_dl_zurnalas'); foreach(array(35434,35436,35414,35799) as $id){ $r=wp_remote_get(admin_url('admin-ajax.php?action=ps_dl_skydelis&id='.$id.'&n='.$n),array('cookies'=>$cs,'timeout'=>60,'sslverify'=>false)); $d=json_decode((string)wp_remote_retrieve_body($r),true)['data']??array(); $o['sk'][$id]=array('kur'=>$d['kur']??null,'apmok'=>$d['apmok']??null,'pastaba'=>mb_substr((string)($d['pastaba']??''),0,220),'klientas_url'=>!empty($d['klientas_url']),'btn'=>$d['btn']['t']??null,'dok'=>count($d['dok']??array())); }
    $r=wp_remote_get(admin_url('admin.php?page=ps-desk&eile=klausimai'),array('cookies'=>$cs,'timeout'=>90,'sslverify'=>false)); $h=(string)wp_remote_retrieve_body($r); $o['klaus_code']=wp_remote_retrieve_response_code($r); $o['eiles']=preg_match_all('/<a class="dl-eile[^"]*"[^>]*>(.*?)<\/a>/su',$h,$ea)?array_map(function($x){return trim(preg_replace('/\s+/',' ',wp_strip_all_tags($x)));},$ea[1]):null; $o['kort_n']=preg_match_all('/<div class="dl-kortele eil"/',$h,$kk);
    $r=wp_remote_get(admin_url('admin.php?page=ps-desk&view=saskaitos'),array('cookies'=>$cs,'timeout'=>90,'sslverify'=>false)); $hs=(string)wp_remote_retrieve_body($r); $o['saskaitos']=array('code'=>wp_remote_retrieve_response_code($r),'h1'=>preg_match('/<h1 class="dl-h1">(.*?)<\/h1>/su',$hs,$h1)?trim(preg_replace('/\s+/',' ',wp_strip_all_tags($h1[1]))):'','rows'=>preg_match_all('/<tbody>(.*?)<\/tbody>/su',$hs,$tb)?preg_match_all('/<tr>/',$tb[1][0],$tr):0);
    $ku=wc_get_order(35436)->get_checkout_order_received_url(); $r=wp_remote_get($ku,array('timeout'=>90,'sslverify'=>false)); $hb=(string)wp_remote_retrieve_body($r); $o['klientas_pusl']=array('code'=>wp_remote_retrieve_response_code($r),'title'=>preg_match('/<title>(.*?)<\/title>/su',$hb,$tt)?trim($tt[1]):'','siuntos'=>(int)(stripos($hb,'Siuntos')!==false),'verif'=>(int)(stripos($hb,'verify-email')!==false),'h2'=>preg_match_all('/<h2[^>]*>(.*?)<\/h2>/su',$hb,$h2)?array_values(array_filter(array_map(function($x){return trim(wp_strip_all_tags($x));},array_slice($h2[1],0,10)))):array());
    $r=wp_remote_get(admin_url('admin.php?page=ps-desk&eile=visi'),array('cookies'=>$cs,'timeout'=>90,'sslverity'=>false,'sslverify'=>false)); $o['visi_code']=wp_remote_retrieve_response_code($r);
    $o['temp_liko']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}snippets WHERE name LIKE 'TEMP%'"); $J($o);
  }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.basename($e->getFile()).':'.$e->getLine(); }
  $J($o);
},99);
